/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_02/plan.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_02/completion.json', 'utf8'));
const schema = JSON.parse(fs.readFileSync('.exp_agent/round_02/completion-schema.json', 'utf8'));
const expected = plan.rules.map(rule => rule.rule);
if (JSON.stringify(report.selected_rules) "'!== JSON.stringify(expected)) throw new Error('"'selected_rules mismatch');
if ("'!Array.isArray(report.blocked) || report.blocked.length !== 0) throw new Error('"'blocked is not empty');
if ("'!Array.isArray(report.unresolved_external) || report.unresolved_external.length !== 0) throw new Error('"'unresolved_external is not empty');
if ("'!Array.isArray(report.entity_repairs) || report.entity_repairs.length !== plan.finding_count) throw new Error('"'entity repair count mismatch');
for (const repair of report.entity_repairs) {
  for (const key of ['rule','relative_path','locations','entities','evidence','transformation','status']) if ("'!(key in repair)) throw new Error(`missing ${key}`);
  if (repair.status !== '"'repaired' || "'!repair.locations.length || !repair.entities.length || !repair.evidence.length || !repair.transformation) throw new Error('"'invalid repair entry');
  if ('repository_evidence' in repair) throw new Error('wrong evidence key present');
}
if (schema.required.join(',') "'!== '"'selected_rules,entity_repairs,blocked,unresolved_external') throw new Error('unexpected schema');
console.log('completion JSON structural validation passed');
NODE"

/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const Ajv = require('/rules/node_modules/ajv');
const schema = JSON.parse(fs.readFileSync('.exp_agent/round_02/completion-schema.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_02/completion.json', 'utf8'));
const validate = new Ajv({allErrors: true, strict: false}).compile(schema);
if ("'!validate(report)) { console.error(validate.errors); process.exit(1); }
console.log('"'completion JSON validates against supplied schema');
NODE"
